def trace(input_data):
    sess = TraceSession(algorithm='Min-Heap', input_data=input_data, pseudocode=['Initialize empty min-heap', 'For each rating: push; if size > k, pop smallest', 'Heap top is k-th highest'])
    nums = input_data['nums']
    k = input_data['k']
    arr = sess.array('nums', nums)
    heap = sess.heap('min_heap', [])
    scalar_k = sess.scalar('k', k)
    answer = None
    for i, num in enumerate(nums):
        with sess.step(f'Process num={num}'):
            arr.highlight(i, role='current')
            heap.push(num, reason=f'Push {num}')
            if len(heap) > k:
                heap.pop(reason=f'Heap size exceeds {k}, pop smallest')
            if not heap.empty():
                current = heap.peek()
                sess.note(f'Current {k}-th highest: {current}')
    answer = heap.peek()
    with sess.step('Final answer'):
        sess.note(f'After all numbers, the {k}-th highest is {answer}')
    sess.result(answer)
    trace = sess.to_trace()
    for event in trace['events']:
        op = event.get('op')
        targets = [t.get('id','') for t in event.get('targets',[])]
        reason = event.get('reason','') or ''
        if op == 'create' and 'nums' in targets:
